interface Notifier {
    void send(String message);

    // Default method provides backwards-compatible implementation
    default void sendWithTimestamp(String msg) {
        System.out.println("[2026-03-01] " + msg);
        send(msg);
    }
}

class EmailNotifier implements Notifier {
